package com.geoffvargo.gvorbabackend.notification;

import com.fasterxml.jackson.annotation.*;

import org.jsoup.*;
import org.jsoup.nodes.*;
import org.springframework.core.io.*;
import org.springframework.stereotype.*;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;

import lombok.extern.slf4j.*;
import tools.jackson.databind.json.*;

/**
 * Turns Tailwind classes in rendered email HTML into inline {@code style} attributes, because
 * email clients ignore stylesheets and CSS variables.
 *
 * <p>The class-to-style map is {@code email/tailwind.json}, generated by running
 * {@code npm run email-css} in the frontend. A class missing from the map means that file needs
 * regenerating.
 */
@Component
@Slf4j
class TailwindInliner {
	static final String RULES_RESOURCE = "email/tailwind.json";

	/// Class name -> its compiled rule. LinkedHashMap keeps Tailwind's CSS order.
	private final Map<String, IndexedRule> rules = new LinkedHashMap<>();
	private final String extraCss;

	/// Unknown classes already logged, so each one is only warned about once.
	private final Set<String> warnedClasses = ConcurrentHashMap.newKeySet();

	/**
	 * Loads the generated map from the classpath. If it's missing, emails are sent unstyled.
	 */
	TailwindInliner() {
		this(openRulesResource());
	}

	/**
	 * Loads the class-to-style map from {@code json}.
	 *
	 * @param json
	 * 	contents of a {@code tailwind.json} file, or {@code null} to inline nothing
	 */
	TailwindInliner(InputStream json) {
		if (json == null) {
			log.warn("{} not found on the classpath; Tailwind classes in emails will not be styled. "
				         + "Run `npm run email-css` in frontend/gvorba-frontend.", RULES_RESOURCE);
			extraCss = "";
			return;
		}

		try (json) {
			CompiledCss css = JsonMapper.builder().build().readValue(json, CompiledCss.class);
			for (Rule rule : css.rules()) {
				rules.put(rule.className(), new IndexedRule(rules.size(), rule.style()));
			}
			extraCss = css.extraCss() == null ? "" : css.extraCss();
		} catch (IOException e) {
			throw new UncheckedIOException("Failed to read " + RULES_RESOURCE, e);
		}
	}

	/**
	 * Writes the styles for each element's Tailwind classes into its {@code style} attribute.
	 * Styles already in the attribute are kept and placed last, so they still win.
	 *
	 * @param html
	 * 	rendered email HTML
	 * @return the same HTML with inline styles
	 */
	String inline(String html) {
		Document doc = Jsoup.parse(html);
		/// Don't reformat the HTML; only the style attributes should change.
		doc.outputSettings().prettyPrint(false);

		for (Element element : doc.select("[class]")) {
			List<IndexedRule> matched = new ArrayList<>();
			for (String className : element.classNames()) {
				IndexedRule rule = rules.get(className);
				if (rule != null) {
					matched.add(rule);
				} else if (warnedClasses.add(className)) {
					log.warn("Email class '{}' has no compiled Tailwind style; run `npm run email-css` "
						         + "in frontend/gvorba-frontend.", className);
				}
			}
			if (matched.isEmpty()) {
				continue;
			}

			/// Apply in CSS order, not class-attribute order, the same way a browser resolves them.
			matched.sort(Comparator.comparingInt(IndexedRule::order));
			StringJoiner style = new StringJoiner("; ");
			matched.forEach(rule -> style.add(rule.style()));

			String existing = element.attr("style").strip();
			if (!existing.isEmpty()) {
				style.add(existing.endsWith(";") ? existing.substring(0, existing.length() - 1) : existing);
			}
			element.attr("style", style.toString());
		}

		/// @media and :hover rules can't be inlined; clients that support <style> still get them.
		if (!extraCss.isEmpty()) {
			doc.head().appendElement("style").appendChild(new DataNode(extraCss));
		}
		return doc.outerHtml();
	}

	/**
	 * Reports whether {@code className} has a compiled style.
	 *
	 * @param className
	 * 	a single class name, e.g. {@code p-6}
	 * @return {@code true} if {@code tailwind.json} has a rule for it
	 */
	boolean hasRule(String className) {
		return rules.containsKey(className);
	}

	private static InputStream openRulesResource() {
		ClassPathResource resource = new ClassPathResource(RULES_RESOURCE);
		try {
			return resource.exists() ? resource.getInputStream() : null;
		} catch (IOException e) {
			throw new UncheckedIOException("Failed to open " + RULES_RESOURCE, e);
		}
	}

	/// Shape of tailwind.json.
	private record CompiledCss(List<Rule> rules, String extraCss) {}

	/// "class" is a Java keyword, so the JSON field is mapped onto className.
	private record Rule(@JsonProperty("class") String className, String style) {}

	private record IndexedRule(int order, String style) {}
}